def solve(nums):
    a = list(nums)
    n = len(a)
    # find pivot
    i = n - 2
    while i >= 0 and a[i] >= a[i+1]:
        i -= 1
    if i == -1:
        return sorted(a)
    # find rightmost successor greater than a[i]
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    a[i], a[j] = a[j], a[i]
    a[i+1:] = reversed(a[i+1:])
    return a

def solve(line: str):
    """Parse a CSV line into a list of fields.
    Supports fields optionally quoted with double quotes. Inside quoted fields,
    commas are treated as literal characters and a pair of double quotes "" represents a literal quote.
    Empty line returns [''].
    """
    fields = []
    cur = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Check for escaped quote
                if i + 1 < n and line[i + 1] == '"':
                    cur.append('"')
                    i += 1  # skip the second quote
                else:
                    in_quotes = False
            else:
                cur.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(cur))
                cur = []
            elif ch == '"':
                # start of a quoted field
                in_quotes = True
            else:
                cur.append(ch)
        i += 1
    # Append last field (even if line ends with a comma, cur will be empty)
    fields.append(''.join(cur))
    return fields

