    cur_len = 0
    for w in words:
        if not current:
            # start new line with w
            current.append(w)
            cur_len = len(w)
        else:
            # try to add with a space
            if cur_len + 1 + len(w) <= width:
                current.append(w)
                cur_len += 1 + len(w)
            else:
                # cannot add, finalize current line
                lines.append(' '.join(current))
                # start new line with w
                current = [w]
                cur_len = len(w)
