def solve(n, edges):
    from heapq import heappush, heappop
    # build adjacency and indegree
    adj = [[] for _ in range(n)]
    indeg = [0]*n
    for a,b in edges:
        adj[a].append(b)
        indeg[b] += 1
    heap = []
    for i in range(n):
        if indeg[i]==0:
            heappush(heap, i)
    order = []
    while heap:
