def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited
    coins from *coins*. Return -1 if impossible.
    Classic unbounded knapsack DP.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # filter out non-positive coin values as they are useless or cause infinite loops
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # Initialize DP array with a sentinel larger than any possible answer
    INF = amount + 1  # because the max needed coins is amount (using coin=1)
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for c in coins:
        for v in range(c, amount + 1):
            # If dp[v - c] is reachable, update dp[v]
            if dp[v - c] + 1 < dp[v]:
                dp[v] = dp[v - c] + 1
    return dp[amount] if dp[amount] != INF else -1

