def solve(n, edges):
    """Return the smallest total weight from node 0 to node n-1 in an undirected weighted graph.
    If n == 1, distance is 0. If node n-1 is unreachable from 0, return -1.
    """
    if n <= 0:
        return -1
    if n == 1:
        return 0
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        if 0 <= a < n and 0 <= b < n and w >= 0:
            adj[a].append((b, w))
            adj[b].append((a, w))
    import heapq
    INF = 10**18
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]  # (distance, node)
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == n - 1:
            # reached target with shortest distance
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1 if dist[n-1] == INF else dist[n-1]

