def solve(coins, amount):
    # Edge cases
    if amount == 0:
        return 0
    if not coins:
        return -1
    # DP array where dp[i] is min coins to make i
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue
        for i in range(coin, amount + 1):
            if dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

def solve(n: int) -> int:
    """Return the number of prime numbers strictly less than *n*.
    Uses the Sieve of Eratosthenes up to n-1. Handles n <= 2 quickly.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)  # True means prime candidate
    sieve[0:2] = b'\x00\x00'  # 0 and 1 are not prime
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:limit + 1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

